type IncidentServiceHTTPClient interface {
	// AcquireAgentLease AcquireAgentLease 取得故障的 Agent 租约（同一时刻至多一个 Agent 任务）；持有者的发现 / 建议标记为 Agent。
	AcquireAgentLease(ctx context.Context, req *AgentLeaseRequest, opts ...http.CallOption) (rsp *IncidentResponse, err error)
	// AddComment AddComment 备注（可带附件）。
	AddComment(ctx context.Context, req *AddCommentRequest, opts ...http.CallOption) (rsp *TimelineItemResponse, err error)
	// AddFinding AddFinding Agent 回写一条发现（须持有租约；只能追加）。
	AddFinding(ctx context.Context, req *AddFindingRequest, opts ...http.CallOption) (rsp *TimelineItemResponse, err error)
	// AssignCommander AssignCommander 指派 / 转交指挥。
	AssignCommander(ctx context.Context, req *AssignCommanderRequest, opts ...http.CallOption) (rsp *IncidentResponse, err error)
	// AttachAlerts AttachAlerts 关联告警（告警已属于别的活跃故障返回 409；可指定 move=true 迁移过来）。
	AttachAlerts(ctx context.Context, req *AttachAlertsRequest, opts ...http.CallOption) (rsp *AttachAlertsResponse, err error)
	// ChangeSeverity ChangeSeverity 调整等级（重新评估通知与复盘要求）。
	ChangeSeverity(ctx context.Context, req *ChangeSeverityRequest, opts ...http.CallOption) (rsp *IncidentResponse, err error)
	// CreateIncident CreateIncident 手动开故障（可同时关联告警）。
	CreateIncident(ctx context.Context, req *CreateIncidentRequest, opts ...http.CallOption) (rsp *CreateIncidentResponse, err error)
	// CreateIncidentTicket CreateIncidentTicket 从故障创建工单（变更单）。
	CreateIncidentTicket(ctx context.Context, req *CreateIncidentTicketRequest, opts ...http.CallOption) (rsp *CreateIncidentTicketResponse, err error)
	// DetachAlert DetachAlert 移出告警。
	DetachAlert(ctx context.Context, req *DetachAlertRequest, opts ...http.CallOption) (rsp *IncidentResponse, err error)
	// DismissCandidate DismissCandidate 忽略候选故障。
	DismissCandidate(ctx context.Context, req *DismissCandidateRequest, opts ...http.CallOption) (rsp *DismissCandidateResponse, err error)
	// GetImpact GetImpact 影响面：受影响资源及其下游。
	GetImpact(ctx context.Context, req *GetImpactRequest, opts ...http.CallOption) (rsp *GetImpactResponse, err error)
	// GetIncident GetIncident 故障详情（基本信息 + 角色 + 关联告警摘要 + 复盘状态）。
	GetIncident(ctx context.Context, req *GetIncidentRequest, opts ...http.CallOption) (rsp *GetIncidentResponse, err error)
	// GetIncidentContext GetIncidentContext 一次返回故障的全部上下文（故障、告警、资源与影响面、变更、时间线、公告、推荐预案、相似故障）：
	// 页面首屏、AI 摘要、页内助手与 Agent 共用；摘要级字段，下钻走各域接口。
	GetIncidentContext(ctx context.Context, req *GetIncidentContextRequest, opts ...http.CallOption) (rsp *GetIncidentContextResponse, err error)
	// ListCandidates ListCandidates 候选故障（触发规则命中但未达开启门槛）。
	ListCandidates(ctx context.Context, req *ListCandidatesRequest, opts ...http.CallOption) (rsp *ListCandidatesResponse, err error)
	// ListChanges ListChanges 变更关联：发生前回看窗口内与受影响资源相关的各域变更（已标注关系的优先）。
	ListChanges(ctx context.Context, req *ListChangesRequest, opts ...http.CallOption) (rsp *ListChangesResponse, err error)
	// ListIncidentAlerts ListIncidentAlerts 关联告警（带当前状态）。
	ListIncidentAlerts(ctx context.Context, req *ListIncidentAlertsRequest, opts ...http.CallOption) (rsp *ListIncidentAlertsResponse, err error)
	// ListIncidentOptions ListIncidentOptions 候选项：值班表 / 通知群 / 用户等表单下拉用（最小披露）。
	ListIncidentOptions(ctx context.Context, req *ListIncidentOptionsRequest, opts ...http.CallOption) (rsp *ListIncidentOptionsResponse, err error)
	// ListIncidents ListIncidents 分页查询故障。
	ListIncidents(ctx context.Context, req *ListIncidentsRequest, opts ...http.CallOption) (rsp *ListIncidentsResponse, err error)
	// ListIncidentsByAlert ListIncidentsByAlert 一条告警所属的故障（活跃的在前）；告警详情页用。免接口授权：持有告警详情权限即可。
	ListIncidentsByAlert(ctx context.Context, req *ListIncidentsByAlertRequest, opts ...http.CallOption) (rsp *ListIncidentsByAlertResponse, err error)
	// ListTimeline ListTimeline 时间线（按时间升序分页，可按类型过滤）。
	ListTimeline(ctx context.Context, req *ListTimelineRequest, opts ...http.CallOption) (rsp *ListTimelineResponse, err error)
	// MarkChange MarkChange 标注一条变更与故障的关系（疑似原因 / 已确认原因 / 无关）。
	MarkChange(ctx context.Context, req *MarkChangeRequest, opts ...http.CallOption) (rsp *MarkChangeResponse, err error)
	// MergeIncident MergeIncident 把本故障合并到另一个故障（告警迁移、角色并入、本故障置已合并）。
	MergeIncident(ctx context.Context, req *MergeIncidentRequest, opts ...http.CallOption) (rsp *IncidentResponse, err error)
	// PinEvent PinEvent 钉住 / 取消钉住一条时间线记录。
	PinEvent(ctx context.Context, req *PinEventRequest, opts ...http.CallOption) (rsp *TimelineItemResponse, err error)
	// PromoteCandidate PromoteCandidate 把候选故障转正为故障。
	PromoteCandidate(ctx context.Context, req *PromoteCandidateRequest, opts ...http.CallOption) (rsp *IncidentResponse, err error)
	// RegenerateSummary RegenerateSummary 重新生成 AI 摘要（排队执行）。
	RegenerateSummary(ctx context.Context, req *RegenerateSummaryRequest, opts ...http.CallOption) (rsp *IncidentResponse, err error)
	// ReleaseAgentLease ReleaseAgentLease 释放 Agent 租约（持有者自己释放，或指挥「停止 Agent」）。
	ReleaseAgentLease(ctx context.Context, req *AgentLeaseRequest, opts ...http.CallOption) (rsp *IncidentResponse, err error)
	// SearchIncidents SearchIncidents 全文检索历史故障（相似故障推荐）。
	SearchIncidents(ctx context.Context, req *SearchIncidentsRequest, opts ...http.CallOption) (rsp *SearchIncidentsResponse, err error)
	// TransitionIncident TransitionIncident 状态流转：respond（响应）/ mitigate（缓解）/ resolve（恢复）/ close（关闭）/ reopen（重开）。
	TransitionIncident(ctx context.Context, req *TransitionIncidentRequest, opts ...http.CallOption) (rsp *IncidentResponse, err error)
	// UpdateIncident UpdateIncident 编辑标题 / 摘要 / 业务 / 受影响资源 / 通知群 / 发生时间 / 演练标记。
	UpdateIncident(ctx context.Context, req *UpdateIncidentRequest, opts ...http.CallOption) (rsp *UpdateIncidentResponse, err error)
	// UpdateMembers UpdateMembers 添加 / 移除处理人与关注人（自己加入关注只需读权限）。
	UpdateMembers(ctx context.Context, req *UpdateMembersRequest, opts ...http.CallOption) (rsp *IncidentResponse, err error)
}

